import gurobipy as gp
from gurobipy import GRB
fixed_costs = {}
service_costs = {}
customers = []
centers = []
for rec in LEGACY_RECORDS:
    v = rec['values']
    if 'Service Center' in v and 'Fixed Opening Cost' in v:
        center = v['Service Center']
        fixed_costs[center] = float(v['Fixed Opening Cost'])
        if center not in centers:
            centers.append(center)
    elif 'Customer' in v:
        cust = v['Customer']
        if cust not in customers:
            customers.append(cust)
        for c in v:
            if c.startswith('SC'):
                if cust not in service_costs:
                    service_costs[cust] = {}
                service_costs[cust][c] = float(v[c])
if set(fixed_costs.keys()) != set(centers):
    raise ValueError('Mismatch in fixed costs and centers.')
for cust in customers:
    if cust not in service_costs or set(service_costs[cust].keys()) != set(centers):
        raise ValueError(f'Missing service costs for customer {cust}.')
m = gp.Model('Service_Centre_Location')
m.Params.MIPGap = 0.0001
y = m.addVars(centers, vtype=GRB.BINARY, name='')
x = m.addVars(customers, centers, vtype=GRB.BINARY, name='')
m.setObjective(gp.quicksum((fixed_costs[j] * y[j] for j in centers)) + gp.quicksum((service_costs[i][j] * x[i, j] for i in customers for j in centers)), GRB.MINIMIZE)
m.addConstrs((gp.quicksum((x[i, j] for j in centers)) == 1 for i in customers), name='')
m.addConstrs((x[i, j] <= y[j] for i in customers for j in centers), name='')
m.addConstrs((gp.quicksum((x[i, j] for i in customers)) <= 4 * y[j] for j in centers), name='')
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for v in m.getVars():
        print(f'{v.VarName}: {v.X}')
else:
    print(f'Solver status: {m.Status}')